      SUBROUTINE MALIGNCC     CALCULATES EFFECT OF MISALIGNMENTSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM8C.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8M.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'CC     LOCAL VARIABLESC      INTEGER        J, M, N, NCOMP      REAL           VMSAV(6)      CHARACTER*4    BLANKC      DATA  BLANK /'    '/CC-------------------------------------------------------------      NCOMP = 0      IF (TYPE .EQ. 2 .OR. TYPE .EQ. 4 .OR. TYPE .EQ. 5     1    .OR. TYPE .EQ. 28 .OR. TYPE .EQ. 29)      2    NCOMP = NMISE      IF (TYPE .EQ. 6 .OR. TYPE .EQ. 8 .OR. TYPE .EQ. 37)      1    NCOMP = NMIS      IF (LTAB .EQ. 1) THEN        DO 10 N = 1, NMMAX        IF (NCOMP .EQ. NMTE(N)) THEN          NM = N          LNMT(NM) = .TRUE.          GO TO 15        ENDIF   10   CONTINUE        WRITE (NOUT,9001) 9001   FORMAT (' NO MATCH FOR MISALIGNMENT SPECIFICATION')        FLUSHL = .TRUE.        GO TO 100C   15   IF (BEFORE) THEN          LABM(NM) = BLANK          LMIS(1,NM) = LC        ELSE          LABM(NM) = LAST(1:8)          LMIS(2,NM) = LC        ENDIF        CHORDT(NM) = CHORD      ENDIFC      IF (LFM .EQ. 0) THEN        IF (.NOT. BEFORE) CALL MUNCH      ELSE IF (LFM .GE. 1) THEN        IF (BEFORE) THEN          IF (CHORD .OR. TMK .GE. 1) CALL OGET          CALL PIVENT        ELSE          CALL OGET          IF (CHORD .OR. TMK .GE. 1) CALL PIVENT          CALL PIVEX        ENDIF        IF (LTAB .EQ. 0) THEN          IF (BEFORE) THEN            CALL MENTER          ELSE            CALL MEXIT          ENDIF        ELSE IF (LTAB .EQ. 1) THEN          DO 20 M = 1, 6   20     VMSAV(M) = VM(M)C          DO 50 M = 1, 6          DO 40 J = 1, 6   40     VM(J) = 0.0          VM(M) = VMSAV(M)          IF (BEFORE) THEN            CALL MENTER          ELSE            CALL MEXIT          ENDIF          CALL JOSTLE(M)   50     CONTINUE          R2PM(NM) = .TRUE.C          DO 60 M = 1, 6   60     VM(M) = VMSAV(M)        ENDIF      ENDIFC  100 RETURN      END